#include <bits/stdc++.h>

#define make_pair mp
#define push_back pb
#define long long ll

using namespace std;

const int MOD = 1000000007;

int parent_array[1111111];
int total_components;

int find_root(int x) {
    if (x == parent_array[x]) return x;
    return parent_array[x] = find_root(parent_array[x]);
}

void union_sets(int a, int b) {
    a = find_root(a);
    b = find_root(b);
    if (a == b) return;
    total_components--;
    parent_array[b] = a;
}

ll power_mod(ll base, int exponent) {
    if (exponent == 0) return 1;
    ll half_pow = power_mod(base, exponent / 2);
    ll res = (half_pow * half_pow) % MOD;
    if (exponent & 1) res = (res * base) % MOD;
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll p, k;
    cin >> p >> k;

    if (k == 0) {
        cout << power_mod(p, p - 1) << '\n';
        return 0;
    }

    total_components = p - (k > 1);
    for (ll i = 1; i < p; i++) parent_array[i] = i;

    for (ll i = 1; i < p; i++) {
        union_sets(i, (i * k) % p);
    }

    cout << power_mod(p, total_components) << '\n';

    return 0;
}
